//! Pairing invitation and lifecycle management for the Windows host.

use crate::error::HostServiceError;
use chrono::{DateTime, Duration, Utc};
use openremote_protocol::pairing::QrPairingPayload;
use openremote_protocol::types::DeviceId;
use std::collections::HashMap;

/// An unconsumed pairing invitation generated by the host.
#[derive(Debug, Clone)]
pub struct PendingInvitation {
    pub token: String,
    pub created_at: DateTime<Utc>,
    pub expires_at: DateTime<Utc>,
}

/// Manages active QR pairing invitations.
#[derive(Debug, Default)]
pub struct PairingManager {
    invitations: HashMap<String, PendingInvitation>,
}

impl PairingManager {
    pub fn new() -> Self {
        Self {
            invitations: HashMap::new(),
        }
    }

    /// Generate a fresh single-use pairing invitation.
    pub fn create_invitation(
        &mut self,
        server_url: &str,
        host_device_id: &DeviceId,
        host_public_key: &str,
        host_display_name: &str,
        validity: Duration,
    ) -> QrPairingPayload {
        self.prune_expired();

        let token = uuid::Uuid::new_v4().to_string();
        let now = Utc::now();
        let expires_at = now + validity;

        let invitation = PendingInvitation {
            token: token.clone(),
            created_at: now,
            expires_at,
        };

        self.invitations.insert(token.clone(), invitation);

        QrPairingPayload {
            server_url: server_url.to_string(),
            invitation_token: token,
            host_public_key: host_public_key.to_string(),
            host_device_id: host_device_id.clone(),
            host_display_name: host_display_name.to_string(),
            expires_at,
        }
    }

    /// Validate that an invitation token is present and not expired, then consume it.
    pub fn validate_and_consume(&mut self, token: &str) -> Result<(), HostServiceError> {
        let invitation = self
            .invitations
            .remove(token)
            .ok_or(HostServiceError::InvalidInvitation)?;

        if Utc::now() > invitation.expires_at {
            return Err(HostServiceError::InvalidInvitation);
        }

        Ok(())
    }

    /// Remove expired invitations from memory.
    pub fn prune_expired(&mut self) {
        let now = Utc::now();
        self.invitations.retain(|_, inv| inv.expires_at > now);
    }

    /// Number of active pending invitations.
    pub fn active_count(&self) -> usize {
        self.invitations.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_invitation_lifecycle() {
        let mut mgr = PairingManager::new();
        let host_id = DeviceId::new();

        let payload = mgr.create_invitation(
            "ws://localhost:8080/ws/signal",
            &host_id,
            "pubkey123",
            "WinHost",
            Duration::minutes(5),
        );

        assert_eq!(mgr.active_count(), 1);
        assert_eq!(payload.host_display_name, "WinHost");

        // First consume succeeds
        assert!(mgr.validate_and_consume(&payload.invitation_token).is_ok());
        assert_eq!(mgr.active_count(), 0);

        // Second consume fails (single-use)
        assert!(mgr.validate_and_consume(&payload.invitation_token).is_err());
    }

    #[test]
    fn test_expired_invitation_rejected() {
        let mut mgr = PairingManager::new();
        let host_id = DeviceId::new();

        // Expired immediately
        let payload = mgr.create_invitation(
            "ws://localhost:8080/ws/signal",
            &host_id,
            "pubkey123",
            "WinHost",
            Duration::seconds(-1),
        );

        assert!(mgr.validate_and_consume(&payload.invitation_token).is_err());
    }
}
